import urllib.request
from bs4 import BeautifulSoup
import csv
import os
# Constants
CSV_FILE_PATH = 'scraped_data.csv'

def task_func(url):
    """
    Fetch a web page, scrape available data, and save it to CSV_FILE_PATH.

    If HTML tables are present, the function extracts table rows.
    Otherwise, it falls back to extracting common text-bearing elements.
    """
    # Fetch page content
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "Mozilla/5.0"}
    )
    with urllib.request.urlopen(request) as response:
        raw_html = response.read()
        charset = response.headers.get_content_charset() or "utf-8"
        html = raw_html.decode(charset, errors="replace")

    soup = BeautifulSoup(html, "html.parser")
    rows = []

    # Prefer tables when available
    tables = soup.find_all("table")
    if tables:
        for table_index, table in enumerate(tables):
            headers = []
            header_row = table.find("tr")
            if header_row:
                headers = [cell.get_text(" ", strip=True) for cell in header_row.find_all(["th", "td"])]

            for row_index, tr in enumerate(table.find_all("tr")):
                cells = tr.find_all(["td", "th"])
                values = [cell.get_text(" ", strip=True) for cell in cells]
                if not values:
                    continue

                record = {
                    "table_index": table_index,
                    "row_index": row_index,
                }

                # Use headers if they match the number of cells; otherwise use generic names
                if headers and len(headers) == len(values):
                    for i, value in enumerate(values):
                        key = headers[i].strip() if headers[i].strip() else f"column_{i}"
                        record[key] = value
                else:
                    for i, value in enumerate(values):
                        record[f"column_{i}"] = value

                rows.append(record)

    # Fallback: extract common text elements
    if not rows:
        for tag in soup.find_all(["h1", "h2", "h3", "h4", "h5", "h6", "p", "li", "a"]):
            text = tag.get_text(" ", strip=True)
            if not text:
                continue
            record = {"tag": tag.name, "text": text}
            if tag.name == "a" and tag.has_attr("href"):
                record["href"] = tag.get("href", "")
            rows.append(record)

    # Final fallback if no structured text was found
    if not rows:
        text = soup.get_text(" ", strip=True)
        rows = [{"text": text}] if text else [{"text": ""}]

    # Determine CSV columns
    fieldnames = []
    seen = set()
    for row in rows:
        for key in row.keys():
            if key not in seen:
                seen.add(key)
                fieldnames.append(key)

    # Save to CSV
    with open(CSV_FILE_PATH, "w", newline="", encoding="utf-8") as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow({field: row.get(field, "") for field in fieldnames})

    return CSV_FILE_PATH
